const users = pm.response.json();

const userId = users[0].id;
const userPhone = users[0].phone;

pm.collectionVariables.set("userId", userId);
pm.collectionVariables.set("userPhone", userPhone);

pm.test("User ID is extracted and stored", function () {
    pm.expect(userId).to.exist;
    pm.expect(userId).to.be.a("number");
});

pm.test("User phone is stored", function () {
    pm.expect(userPhone).to.exist;
    pm.expect(userPhone).to.not.equal("");
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const user = pm.response.json();

pm.test("Returned user ID matches stored user ID", function () {
    pm.expect(user.id).to.eql(
        Number(pm.collectionVariables.get("userId"))
    );
});

const randomNumber = Math.floor(Math.random() * 9000) + 1000;

pm.collectionVariables.set(
    "randomName",
    `Test User ${randomNumber}`
);

pm.collectionVariables.set(
    "randomEmail",
    `testuser${randomNumber}@example.com`
);

pm.collectionVariables.set(
    "randomCompany",
    `Test Company ${randomNumber}`
);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const responseData = pm.response.json();

const storedUserId = Number(
    pm.collectionVariables.get("userId")
);

const storedUserPhone =
    pm.collectionVariables.get("userPhone");

pm.test("Returned ID matches stored user ID", function () {
    pm.expect(responseData.id).to.eql(storedUserId);
});

pm.test("Phone is not empty", function () {
    pm.expect(storedUserPhone).to.exist;
    pm.expect(storedUserPhone).to.not.equal("");
});
